import get from 'lodash/get'
import { DEPENDENT_AGENT_ACTIONS } from './actions'

export const INITIAL_STATE = {

}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case DEPENDENT_AGENT_ACTIONS.GET_DEPENDENT_AGENT:
      return {
        ...state,
        getDependentAgentData: [
          ...(state.getDependentAgentData || []),
          ...get(payload, 'getDependentAgentData.data', [])
        ],
        getDependentAgentMetaData: get(payload, 'getDependentAgentData.meta_data', {})
      }
    case DEPENDENT_AGENT_ACTIONS.RESET_DEPENDENT_STATE:
      return {
        ...state,
        ...payload
      }
    default:
      return {
        ...(state || {})
      }
  }
}

export default reducer
