import { useCallback, useEffect, useRef } from 'react'
import { connect } from 'react-redux'
import { Container, CustomText } from '../../../../../../components'
import { LANG_STRINGS } from '../../../../../../lang'
import { DependentAgentsHeader, DependentCardSection, DependentNotExist, LoaderContainer, DependentAgentStyle } from './index.style'
import { AgentColorPallette } from '../../../../../../configs/colorPallete'
import DependentAgentCard from '../../../components/DependentAgentCard'
import authActions from '../../../../../../redux/auth/action'
import { ImageUrl } from '../../../../../../images'
import { useGetDependentAgentsData, useResetDependentState } from '../state/hooks/useDependentAgent'
import { useLoaderContextValue, updateLoader } from '@pasarpolis/common-react-hooks'
import CircularLoader from '../../../../../../components/CircularLoader'
import get from 'lodash/get'
import debounce from 'lodash/debounce'
import { useUpdateGlobal } from '../../../../../../state/globalState/hooks/useGlobalContext'
import Heading from '../../../../../../components/Heading'

const { updateIsGuardianAgent } = authActions

function DependentAgentsContainer (props) {
  const { updateIsGuardianAgent } = props
  // const [query, setQuery] = useState('')

  const loaderRef = useRef(null)
  const observer = useRef(null)
  const elementState = useRef({})
  const listConfig = useRef({
    page: 1,
    page_size: 10
  })

  const [{ GET_DEPENDENT_AGENT_LOADER }, dispatchLoader] = useLoaderContextValue()
  const [ {agentDetails = {}}, updateGlobalStore] = useUpdateGlobal()
  const { category } = agentDetails
  const [
    {
      getDependentAgentData = [],
      getDependentAgentMetaData = {}
    }, getDependentAgentsRequest
  ] = useGetDependentAgentsData()
  const resetDependentState = useResetDependentState()

  const getDependentAgentList = useCallback((query) => {
    getDependentAgentsRequest({
      query: {
        ...query,
        ...listConfig.current
      }
    })
  }, [getDependentAgentsRequest])

  useEffect(() => {
    if (GET_DEPENDENT_AGENT_LOADER === undefined) {
      getDependentAgentList()
    }
    // this used to handle the load more data
    const handleObserver = (entities) => {
      const entity = entities[0]
      const y = entity.boundingClientRect.y
      const screenInnerHeight = window.screen.height
      if (
        ((elementState.current.prevY > screenInnerHeight) && (y < screenInnerHeight)) &&
        (elementState.current.prevY > y) && entity.isIntersecting &&
        (listConfig.current.page < getDependentAgentMetaData.num_page)
      ) {
        listConfig.current.page = listConfig.current.page + 1
        const query = {
          ...listConfig.current
        }
        getDependentAgentList({ ...query })
      }
      elementState.current.prevY = y
    }

    observer.current = new IntersectionObserver(
      handleObserver,
      {
        root: null,
        rootMargin: '0px',
        threshold: 1.0
      }
    )

    // if the loader current exist only then assign to observer
    if (loaderRef.current) {
      observer.current.observe(loaderRef.current)
    }

    return () => {
      observer.current.disconnect()
    }
  }, [
    GET_DEPENDENT_AGENT_LOADER, getDependentAgentList,
    dispatchLoader, getDependentAgentMetaData
  ])

  useEffect(() => {
    return () => {
      dispatchLoader(updateLoader({
        GET_DEPENDENT_AGENT_LOADER: undefined
      }))
    }
  }, [dispatchLoader])

  const handleInputChange = debounce((val) => {
    const search = val
    listConfig.current = {
      page: 1,
      page_size: 10
    }
    resetDependentState({
      getDependentAgentData: [],
      getDependentAgentMetaData: {}
    })
    // call the api after 100ms so
    // that we can update the context state
    setTimeout(() => {
      getDependentAgentList({
        search
      })
    }, 100)
  }, 200)

  const handleUpdateGurdianAgent = useCallback((data) => {
    updateIsGuardianAgent(data)
    updateGlobalStore({
      isGuardianAgentLogin: data
    })
    dispatchLoader(updateLoader({
      GET_AGENT_DETAIL_LOADER: undefined
    }))
  }, [updateIsGuardianAgent, updateGlobalStore, dispatchLoader])

  return (
    <Container
      title={LANG_STRINGS.partnerList}
      showSearchBar
      onSearch={handleInputChange}
      bgColor={AgentColorPallette.primary}
      loader={GET_DEPENDENT_AGENT_LOADER && !getDependentAgentMetaData.total_records}
      activeTab='profile'
      searchPlaceHolder={
        category === 'LV_ADMIN'
        ? 'Cari dengan Nama Mitra atau Nomor Ponsel'
        : undefined
      }
    >
      <DependentAgentStyle>
        <DependentAgentsHeader>
          <Heading
            title={LANG_STRINGS.myPartners}
            size='18px'
          />
          <CustomText
            size='13px'
            color={AgentColorPallette.black}
            className='sub-heading'
          >
            {LANG_STRINGS.pleaseSelectThePartnerToWhichYouWant}
          </CustomText>
        </DependentAgentsHeader>
        <div className='full-line' />
        {
          getDependentAgentData.length ? (
            <DependentCardSection>
              {
                getDependentAgentData.map(agent => (
                  <DependentAgentCard
                    agent={agent.dependent_agent}
                    key={agent.id}
                    onUpdateGuardian={handleUpdateGurdianAgent}
                  />
                ))
              }
            </DependentCardSection>
          ) : !getDependentAgentData && (
            <DependentNotExist>
              <img className='empty-box' src={ImageUrl.emptyBox} alt='Agent Not Exist' />
              <CustomText
                size='16px'
                weight={800}
                lineHeight={1.5}
                top='30px'
                color={AgentColorPallette.fontSecondary}
                textAlign='center'
                className='dependent-not-exist'
              >
                {LANG_STRINGS.youDonotHavePartners}
              </CustomText>
            </DependentNotExist>
          )
        }
        {
          !!get(getDependentAgentData, 'length', 0) &&
          (get(getDependentAgentMetaData, 'num_page', 0) !== listConfig.current.page) &&
          (
            <LoaderContainer id='dependentList-list-loader' ref={loaderRef}>
              <CircularLoader isLoading />
            </LoaderContainer>
          )
        }
      </DependentAgentStyle>
    </Container>
  )
}

export default connect(
  (state) => ({

  }),
  {
    updateIsGuardianAgent
  }
)(DependentAgentsContainer)
