import { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'

// this to create context
export const DependentAgentContext = createContext()

// Context Provider
export const DependentsAgentContextProvider = (props) => {
  return (
    <DependentAgentContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </DependentAgentContext.Provider>
  )
}

// use context value
export const useDependentContextValue = () => useContext(DependentAgentContext)
