import { ConfigUrl } from '../../../../../../configs/url'

export const DEPENDENT_AGENT_ACTIONS = {
  GET_DEPENDENT_AGENT_REQUEST: 'GET_DEPENDENT_AGENT_REQUEST',
  GET_DEPENDENT_AGENT: 'GET_DEPENDENT_AGENT',

  RESET_DEPENDENT_STATE: 'RESET_DEPENDENT_STATE'
}

export const getDependentAgentsAction = (payload) => ({
  type: DEPENDENT_AGENT_ACTIONS.GET_DEPENDENT_AGENT_REQUEST,
  payload: {
    ...payload,
    method: 'GET',
    url: ConfigUrl.dependentAgentsApi
  }
})

export const resetDependentAgentState = (payload) => ({
  type: DEPENDENT_AGENT_ACTIONS.RESET_DEPENDENT_STATE,
  payload
})
