import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import { useDependentContextValue } from '../../context'
import { getDependentAgentsAction, resetDependentAgentState } from '../actions'

export const useDependentAgentsServiceCall = (actionsCall = () => {}) => {
  const [dependentAgentsState, dispatch] = useDependentContextValue()
  const [callApi] = useServiceRequest(dispatch)

  const request = async (payload = {}) => {
    await callApi(actionsCall({
      ...payload
    }))
  }

  return [dependentAgentsState, request]
}

export const useGetDependentAgentsData = () => {
  return useDependentAgentsServiceCall(getDependentAgentsAction)
}

export const useResetDependentState = () => {
  const [, dispatch] = useDependentContextValue()
  return (payload = {}) => {
    dispatch(resetDependentAgentState(payload))
  }
}
