import { Component } from 'react'
import PropTypes from 'prop-types'
import Cookies from 'universal-cookie'
import { Row } from '../../../../../commonStyle/index.style'
import { DependentAgentCardStyle } from './index.style'
import { CustomText } from '../../../../../components'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
import {
  LOGIN_AS_GURDIAN,
  LOGIN_INFO_MODAL,
  REDIRECT_AFTER_REFRESH,
  GUARDIAN_PRODUCT_REDIRECT,
} from '../../../../../constants/cookies'
import get from 'lodash/get'
import { withRouter } from 'react-router'
import { ARROW_RIGHT_ICON } from '../../../../../images'

const cookies = new Cookies()

class DependentAgentCard extends Component {
  static propTypes = {
    agent: PropTypes.object,
    onUpdateGuardian: PropTypes.func,
  }

  handleLoginAsAgent = () => {
    // set the cookies and move to dashboard and get the details with this code now
    // to login as guardian
    cookies.remove(LOGIN_INFO_MODAL, {
      path: '/',
    })
    const dependentCode = get(this.props, 'agent.agent_code', '')
    cookies.set(LOGIN_AS_GURDIAN, dependentCode, {
      path: '/',
      maxAge: 60 * 60 * 24, // store for 1 month
    })

    const productRedirect = sessionStorage.getItem(GUARDIAN_PRODUCT_REDIRECT)
    sessionStorage.removeItem(GUARDIAN_PRODUCT_REDIRECT)
    sessionStorage.setItem(REDIRECT_AFTER_REFRESH, productRedirect || '/dashboard')

    this.props.onUpdateGuardian(dependentCode)

    // Force refresh to reset redux state
    window.location.reload()
  }

  render() {
    const { agent } = this.props
    return (
      <DependentAgentCardStyle
        justify="space-between"
        align="center"
        onClick={this.handleLoginAsAgent}
      >
        <Row align="center">
          <div>
            <CustomText
              color={AgentColorPallette.black}
              size="14px"
              weight={700}
              bottom="4px"
              className="text-transform-capital"
            >
              {agent.name}
            </CustomText>
            <CustomText color={AgentColorPallette.fontSecondary}>{agent.phone_no}</CustomText>
          </div>
        </Row>
        <div>
          <img src={ARROW_RIGHT_ICON} alt="" />
        </div>
      </DependentAgentCardStyle>
    )
  }
}

export default withRouter(DependentAgentCard)
